import { jest } from '@jest/globals';
import { AIPlanningAssistantService } from '../../src/services/aiPlanningAssistant';
import { prisma } from '../../src/prisma';
import logger from '../../src/logger';

// Mock dependencies - OpenAI is already mocked via moduleNameMapper in jest.config.js
jest.mock('../../src/prisma');
jest.mock('../../src/logger');

describe('AIPlanningAssistantService', () => {
  let service: AIPlanningAssistantService;
  const mockLogger = {
    info: jest.fn(),
    warn: jest.fn(),
    error: jest.fn(),
    debug: jest.fn(),
  };
  const mockPrisma = prisma as jest.Mocked<typeof prisma>;

  beforeEach(() => {
    jest.clearAllMocks();
    // Reset environment variable
    delete process.env.OPENAI_API_KEY;

    // Setup logger mock
    (logger as any).info = mockLogger.info;
    (logger as any).warn = mockLogger.warn;
    (logger as any).error = mockLogger.error;
    (logger as any).debug = mockLogger.debug;
  });

  describe('initialization', () => {
    it('should initialize without OpenAI API key', () => {
      service = new AIPlanningAssistantService();
      expect(service).toBeDefined();
      
      // The service should log a warning when no API key is present
      // Since the logger is part of BaseService, we just verify the service is created
    });

    it('should initialize with OpenAI API key', () => {
      process.env.OPENAI_API_KEY = 'test-api-key';
      service = new AIPlanningAssistantService();
      expect(service).toBeDefined();
    });
  });

  describe('generateLongRangeGoals', () => {
    beforeEach(() => {
      process.env.OPENAI_API_KEY = 'test-api-key';
      service = new AIPlanningAssistantService();
    });

    it('should generate long-range goals successfully', async () => {
      const input = {
        subject: 'Mathematics',
        gradeLevel: 3,
        term: 'Fall 2024',
        focusAreas: ['Number Sense', 'Geometry'],
        studentNeeds: 'Visual learners, ESL support needed',
      };

      const result = await service.generateLongRangeGoals(input);
      
      // Since OpenAI is mocked, we get a standard mock response
      expect(result).toBeDefined();
      expect(result.suggestions).toBeDefined();
      expect(Array.isArray(result.suggestions)).toBe(true);
    });

    it('should handle missing focus areas', async () => {
      const input = {
        subject: 'Mathematics',
        gradeLevel: 3,
        term: 'Fall 2024',
        focusAreas: [],
        studentNeeds: 'Mixed abilities',
      };

      const result = await service.generateLongRangeGoals(input);
      
      expect(result).toBeDefined();
      expect(result.suggestions).toBeDefined();
    });

    it('should handle API errors gracefully', async () => {
      const input = {
        subject: 'Mathematics',
        gradeLevel: 3,
        term: 'Fall 2024',
        focusAreas: ['Number Sense'],
        studentNeeds: 'Mixed abilities',
      };

      // Force an error by removing the API key mid-test
      delete process.env.OPENAI_API_KEY;
      
      const result = await service.generateLongRangeGoals(input);
      
      // Should return empty suggestions when API fails
      expect(result.suggestions).toEqual([]);
      expect(result.rationale).toContain('unavailable');
    });

    it('should handle missing API key', async () => {
      delete process.env.OPENAI_API_KEY;
      service = new AIPlanningAssistantService();

      const input = {
        subject: 'Mathematics',
        gradeLevel: 3,
        term: 'Fall 2024',
        focusAreas: ['Number Sense'],
        studentNeeds: 'Mixed abilities',
      };

      const result = await service.generateLongRangeGoals(input);
      
      expect(result.suggestions).toEqual([]);
      expect(result.rationale).toContain('AI service unavailable');
    });
  });

  describe('generateUnitBigIdeas', () => {
    beforeEach(() => {
      process.env.OPENAI_API_KEY = 'test-api-key';
      service = new AIPlanningAssistantService();
    });

    it('should generate unit big ideas successfully', async () => {
      const mockExpectations = [
        {
          id: 1,
          code: 'M3.NS.1',
          description: 'Understand place value to 1000',
          type: 'specific',
          grade: '3',
          subject: 'Mathematics',
          strand: 'Number Sense',
        },
      ];

      (mockPrisma.curriculumExpectation.findMany as jest.Mock).mockResolvedValue(
        mockExpectations,
      );

      const input = {
        unitTitle: 'Place Value and Number Patterns',
        subject: 'Mathematics',
        gradeLevel: 3,
        curriculumExpectationIds: [1],
        duration: '3 weeks',
      };

      const result = await service.generateUnitBigIdeas(input);
      
      expect(result).toBeDefined();
      expect(result.bigIdeas).toBeDefined();
      expect(Array.isArray(result.bigIdeas)).toBe(true);
    });

    it('should handle empty curriculum expectations', async () => {
      (mockPrisma.curriculumExpectation.findMany as jest.Mock).mockResolvedValue([]);

      const input = {
        unitTitle: 'Place Value and Number Patterns',
        subject: 'Mathematics',
        gradeLevel: 3,
        curriculumExpectationIds: [1, 2, 3],
        duration: '3 weeks',
      };

      const result = await service.generateUnitBigIdeas(input);
      
      expect(result).toBeDefined();
      expect(result.connections).toEqual([]);
    });
  });

  describe('generateLessonActivities', () => {
    beforeEach(() => {
      process.env.OPENAI_API_KEY = 'test-api-key';
      service = new AIPlanningAssistantService();
    });

    it('should generate lesson activities with materials', async () => {
      const input = {
        lessonTopic: 'Introduction to Multiplication',
        learningGoals: ['Understand multiplication as repeated addition'],
        subject: 'Mathematics',
        gradeLevel: 3,
        duration: 60,
        materials: ['Base-10 blocks', 'Multiplication chart'],
        differentiationNeeds: 'Visual supports, peer tutoring',
      };

      const result = await service.generateLessonActivities(input);
      
      expect(result).toBeDefined();
      expect(result.activities).toBeDefined();
      expect(Array.isArray(result.activities)).toBe(true);
    });

    it('should generate activities without materials', async () => {
      const input = {
        lessonTopic: 'Mental Math Strategies',
        learningGoals: ['Practice mental addition strategies'],
        subject: 'Mathematics',
        gradeLevel: 3,
        duration: 45,
        materials: [],
        differentiationNeeds: 'Advanced group needs extension',
      };

      const result = await service.generateLessonActivities(input);
      
      expect(result).toBeDefined();
      expect(result.activities).toBeDefined();
    });
  });

  describe('generateMaterialsList', () => {
    beforeEach(() => {
      process.env.OPENAI_API_KEY = 'test-api-key';
      service = new AIPlanningAssistantService();
    });

    it('should generate materials list for activities', async () => {
      const input = {
        activities: [
          {
            name: 'Fraction Pizza Party',
            description: 'Students create paper pizzas to learn fractions',
            type: 'hands-on',
          },
          {
            name: 'Fraction War Card Game',
            description: 'Card game to compare fractions',
            type: 'game',
          },
        ],
        existingMaterials: ['Scissors', 'Glue sticks'],
        budget: 'low',
        classSize: 24,
      };

      const result = await service.generateMaterialsList(input);
      
      expect(result).toBeDefined();
      expect(result.required).toBeDefined();
      expect(Array.isArray(result.required)).toBe(true);
    });
  });

  describe('generateAssessmentStrategies', () => {
    beforeEach(() => {
      process.env.OPENAI_API_KEY = 'test-api-key';
      service = new AIPlanningAssistantService();
    });

    it('should generate varied assessment strategies', async () => {
      const input = {
        unitTitle: 'Ecosystems and Habitats',
        learningGoals: [
          'Identify components of ecosystems',
          'Explain food chains',
          'Understand human impact on habitats',
        ],
        subject: 'Science',
        gradeLevel: 4,
        assessmentPreferences: ['Performance tasks', 'Observations'],
      };

      const result = await service.generateAssessmentStrategies(input);
      
      expect(result).toBeDefined();
      expect(result.formative).toBeDefined();
      expect(result.summative).toBeDefined();
    });
  });

  describe('generateReflectionPrompts', () => {
    beforeEach(() => {
      process.env.OPENAI_API_KEY = 'test-api-key';
      service = new AIPlanningAssistantService();
    });

    it('should generate reflection prompts with previous reflections context', async () => {
      const input = {
        lessonTopic: 'Writing Persuasive Paragraphs',
        learningGoals: ['Write topic sentences', 'Use evidence effectively'],
        studentLevel: 'Grade 5',
        previousReflections: [
          'Students struggled with finding evidence',
          'Topic sentences were too general',
        ],
      };

      const result = await service.generateReflectionPrompts(input);
      
      expect(result).toBeDefined();
      expect(result.studentPrompts).toBeDefined();
      expect(result.teacherPrompts).toBeDefined();
    });

    it('should generate prompts without previous reflections', async () => {
      const input = {
        lessonTopic: 'Introduction to Probability',
        learningGoals: ['Understand likelihood', 'Use probability vocabulary'],
        studentLevel: 'Grade 6',
        previousReflections: [],
      };

      const result = await service.generateReflectionPrompts(input);
      
      expect(result).toBeDefined();
      expect(result.studentPrompts).toBeDefined();
      expect(Array.isArray(result.studentPrompts)).toBe(true);
    });
  });

  describe('getCurriculumAlignedSuggestions', () => {
    beforeEach(() => {
      process.env.OPENAI_API_KEY = 'test-api-key';
      service = new AIPlanningAssistantService();
    });

    it('should generate curriculum-aligned activities', async () => {
      const mockExpectations = [
        {
          id: 1,
          code: 'S4.LS.1',
          description: 'Analyze ecosystems and food chains',
          type: 'specific',
          grade: '4',
          subject: 'Science',
          strand: 'Life Systems',
        },
      ];

      (mockPrisma.curriculumExpectation.findMany as jest.Mock).mockResolvedValue(
        mockExpectations,
      );

      const input = {
        expectationIds: [1],
        requestType: 'activities',
        gradeLevel: 4,
        subject: 'Science',
        constraints: {
          timeLimit: 45,
          materials: 'basic classroom supplies',
          groupSize: 'pairs',
        },
      };

      const result = await service.getCurriculumAlignedSuggestions(input);
      
      expect(result).toBeDefined();
      expect(Array.isArray(result)).toBe(true);
    });

    it('should handle empty expectation IDs', async () => {
      const input = {
        expectationIds: [],
        requestType: 'activities',
        gradeLevel: 4,
        subject: 'Science',
        constraints: {},
      };

      const result = await service.getCurriculumAlignedSuggestions(input);
      
      expect(result).toEqual([]);
    });

    it('should handle no expectations found', async () => {
      (mockPrisma.curriculumExpectation.findMany as jest.Mock).mockResolvedValue([]);

      const input = {
        expectationIds: [999],
        requestType: 'resources',
        gradeLevel: 4,
        subject: 'Science',
        constraints: {},
      };

      const result = await service.getCurriculumAlignedSuggestions(input);
      
      expect(result).toEqual([]);
    });
  });

  describe('getServiceHealth', () => {
    it('should report unhealthy when API key is missing', async () => {
      delete process.env.OPENAI_API_KEY;
      service = new AIPlanningAssistantService();

      const health = await service.getServiceHealth();
      
      expect(health.status).toBe('unhealthy');
      expect(health.message).toContain('API key not configured');
    });

    it('should report healthy when API is configured', async () => {
      process.env.OPENAI_API_KEY = 'test-api-key';
      service = new AIPlanningAssistantService();

      const health = await service.getServiceHealth();
      
      // Since OpenAI is mocked, it should report as healthy
      expect(health.status).toBe('healthy');
    });
  });
});